node -e '
const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if (!m) throw new Error("No script tag found");
const code = m[1].split("// =========================================================================\n    // 3. ESTADO")[0];
const fn = new Function(code + "; return { ELEMENTS, RAW_RECIPES, STARTERS, RECIPES };");
const { ELEMENTS, RAW_RECIPES, STARTERS, RECIPES } = fn();

const keys = new Set();
const dupes = [];
for (const [a, b, out] of RAW_RECIPES) {
  if (!ELEMENTS[a]) console.error("Missing input A:", a);
  if (!ELEMENTS[b]) console.error("Missing input B:", b);
  if (!ELEMENTS[out]) console.error("Missing output:", out);
  const k = a < b ? `${a}+${b}` : `${b}+${a}`;
  if (keys.has(k)) dupes.push(`${k} -> ${out} (already ${RECIPES.get(k)})`);
  keys.add(k);
}

const reached = new Set(STARTERS);
let changed = true;
while (changed) {
  changed = false;
  for (const [a, b, out] of RAW_RECIPES) {
    if (reached.has(a) && reached.has(b) && !reached.has(out)) {
      reached.add(out);
      changed = true;
    }
  }
}

const allIds = Object.keys(ELEMENTS);
const unreachable = allIds.filter(id => !reached.has(id));
console.log("Total elements:", allIds.length);
console.log("Total raw recipes:", RAW_RECIPES.length);
console.log("Unique recipes:", RECIPES.size);
console.log("Dupes:", dupes);
console.log("Reached:", reached.size, "/", allIds.length);
console.log("Unreachable:", unreachable);
if (unreachable.length > 0 || dupes.length > 0) process.exit(1);
'

